          "html": "<p>Сварка — способ получения неразъёмного соединения деталей за счёт местного нагрева до расплавления (сварка плавлением) или пластической деформации (сварка давлением). В сварочном производстве ведущее место занимает дуговая сварка.</p>\n<p>При сварке плавлением кромки основного металла и при необходимости присадочный материал образуют сварочную ванну. После кристаллизации получается сварной шов, а рядом формируется зона термического влияния (ЗТВ).</p>\n<p>В 1802 г. В.В. Петров открыл явление электрической дуги. В 1882 г. Н.Н. Бенардос предложил дуговую сварку неплавящимся угольным электродом; в 1888 г. Н.Г. Славянов — сварку плавящимся металлическим электродом. Позже появились покрытые электроды, сварка под флюсом, в защитных газах и электрошлаковая сварка.</p>\n<p>Знание процессов в дуге и ванне позволяет обоснованно выбирать способ сварки, режим и материалы — это основа качественного шва и безопасной работы.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> История и основы — по учебному пособию Васильева (ТПУ, 2011).</div>",
