          "html": "<p>Сварочная дуга — устойчивый электрический разряд в газе между электродом и изделием (или между электродами). Через дуговой промежуток проходит ток, выделяется большое количество теплоты, достаточное для плавления металла.</p>\n<p>В дуге выделяют катодную область, столб дуги и анодную область. Длина дуги — расстояние между концом электрода и поверхностью ванны. Слишком длинная дуга ухудшает защиту и формирование шва, повышает разбрызгивание и риск пор.</p>\n<p>На постоянном токе различают прямую полярность (электрод «−», изделие «+») и обратную (наоборот). Выбор полярности влияет на распределение тепла между электродом и изделием и на поведение покрытия/проволоки.</p>\n<p>Стабильность дуги зависит от рода тока, длины дуги, состава покрытия или защитного газа и квалификации сварщика. Умение поддерживать короткую устойчивую дугу — базовый навык при РДС и важный фактор качества при других процессах.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Разделы о природе дуги — в пособии Васильева (ТПУ, 2011).</div>",
