          "html": "<p>Дефекты делят на две группы: 1) связанные с металлургией и тепловыми процессами при образовании и кристаллизации ванны; 2) связанные с нарушением техники и режима (подготовка, манипуляция, параметры).</p><h3>Наружные дефекты</h3><ul><li><strong>Наплыв</strong> — натекание жидкого металла на холодный основной без сплавления (капли или протяжённые участки).</li><li><strong>Подрез</strong> — канавка в основном металле вдоль края шва; ослабляет сечение. Часто: большой ток и длинная дуга.</li><li><strong>Прожог</strong> — сквозное отверстие из‑за вытекания ванны: большой зазор, малое притупление, избыток тепла, задержка дуги.</li><li><strong>Нарушение формы</strong> — неровный валик, смещение кромок, неверный катет/усиление.</li></ul><h3>Внутренние и опасные дефекты</h3><ul><li><strong>Непровар / несплавление</strong> — местное несплавление кромок или валиков; уменьшает сечение и даёт концентраторы напряжений.</li><li><strong>Трещины</strong> — в шве или ЗТВ, вдоль/поперёк; горячие (при кристаллизации) и холодные (после остывания). Одни из самых опасных дефектов.</li><li><strong>Шлаковые включения</strong> — из‑за плохой зачистки, длинной дуги, неправильной манипуляции.</li><li><strong>Газовые поры</strong> — газы не успели выйти при кристаллизации: влага, загрязнения, влажные электроды, срыв защиты, повышенный углерод в ряде случаев.</li></ul><h3>Дефекты микроструктуры</h3><p>К ним относят оксиды и неметаллические включения, микропоры/микротрещины, крупное зерно, перегрев и пережог. Перегрев — чрезмерный рост зерна и охрупчивание; пережог — окисление по границам зёрен, часто неисправим переваркой «как есть».</p><p>Порядок действий: вид дефекта → причина → устранить причину → разделать и переварить → контроль.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (дефекты); методы НК — отдельные ГОСТ.</div>",
