          "html": "<p>Сварочные напряжения — внутренние силовые воздействия в сечении из‑за неравномерного нагрева и усадки. Они могут быть растягивающими, сжимающими, изгибающими, крутящими. Деформации — изменение формы и размеров конструкции.</p><h3>Основные причины</h3><ul><li>Неравномерный нагрев зоны сварки и прилегающих участков: горячий металл расширяется сильнее холодного → концентрация напряжений между слоями.</li><li>Усадка при кристаллизации и остывании шва и ЗТВ.</li><li>Неравномерное распределение тепла по толщине и длине.</li></ul><h3>Побочные (технологические) причины</h3><ul><li>Неверный электрод/режим, плохая подготовка деталей.</li><li>Неудачный тип швов или малое расстояние между ними.</li><li>Жёсткое закрепление без учёта усадки, несимметричная укладка валиков.</li></ul><h3>Как снижать</h3><ul><li>Обратноступенчатый способ, короткие участки, симметрия швов.</li><li>Разумные катеты (не наплавлять лишнее).</li><li>Правильные прихватки и приспособления; при необходимости — предварительный выгиб.</li><li>Подогрев и термообработка — только по технологии на марку стали.</li></ul><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (напряжения и деформации); Васильев.</div>",
