          "html": "<p>Свариваемость — способность материала давать при данном виде сварки неразъёмное соединение, способное работать наряду с основным металлом.</p><h3>Физическая и технологическая</h3><ul><li><strong>Физическая</strong> — принципиальная способность образовать металлическую связь.</li><li><strong>Технологическая</strong> — способность получить годное соединение при выбранной технологии (режим, подогрев, присадка, термообработка).</li></ul><h3>Роль углерода</h3><p>С ростом углерода и ряда легирующих элементов свариваемость ухудшается: растёт склонность к закалке и холодным трещинам. Для оценки используют углеродный эквивалент Сэ.</p><h3>Четыре группы</h3><ul><li><strong>Хорошо сваривающиеся</strong> — Сэ ≤ 0,25 %: без закалочных структур и трещин в широком диапазоне режимов.</li><li><strong>Удовлетворительно</strong> — Сэ = 0,25…0,35 %: при правильном режиме мало склонны к холодным трещинам; иногда нужен подогрев.</li><li><strong>Ограниченно</strong> — Сэ = 0,36…0,45 %: склонны к трещинам; нужен подогрев, режим ограничен.</li><li><strong>Плохо</strong> — Сэ > 0,45 %: сильная склонность к закалке и трещинам; подогрев, спецприёмы, термообработка.</li></ul><p>Перед сваркой неизвестной стали уточняйте марку и требования технологии — «варить как Ст3» нельзя.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (свариваемость); расчёт Сэ — по принятой формуле в вашей программе обучения.</div>",
