          "html": "<p>Источник питания обеспечивает ток и напряжение для устойчивого горения дуги. От его характеристики зависят зажигание, стабильность и безопасность.</p><h3>Что важно знать сварщику</h3><ul><li>Род тока: переменный (AC) или постоянный (DC); для DC — прямая/обратная полярность.</li><li>Внешняя характеристика: для РДС обычно крутопадающая; для полуавтомата — жёсткая/пологопадающая (по типу процесса).</li><li>ПВ (продолжительность включения), диапазон тока, холостой ход.</li><li>Мобильность: цеховой аппарат или сварочный агрегат (с двигателем) для площадки.</li></ul><p>Перед работой проверяют кабели, разъёмы, заземление корпуса, отсутствие повреждений. Неисправный источник — риск поражения током и нестабильной дуги.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (источники питания); паспорт конкретного аппарата.</div>",
