          "html": "<p>Ручная дуговая сварка покрытым электродом (РДС, MMA) — процесс, при котором дуга горит между покрытым электродом и изделием. Сварщик вручную подаёт электрод в зону сварки и ведёт шов.</p>\n<p>Покрытие электрода стабилизирует дугу, защищает ванну газами и шлаком, может легировать металл шва. Шлаковая корка формируется на поверхности валика и после остывания удаляется.</p>\n<p>Достоинства РДС: универсальность положений, простота оборудования, возможность работы в монтаже. Недостатки: сравнительно низкая производительность и сильная зависимость качества от квалификации сварщика.</p>\n<p>РДС применяют для сталей и ряда других материалов при изготовлении и ремонте конструкций, когда важны доступность и гибкость процесса.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Технология РДС — Васильев, гл. 12; электроды — ГОСТ 9466, 9467.</div>",
