          "html": "<p>Покрытый электрод — стержень + покрытие. Покрытие усиливает ионизацию, защищает ванну и обрабатывает металл шва металлургически.</p><h3>Типы покрытий (практика)</h3><ul><li><strong>Кислые (A)</strong> — много оксидов железа/марганца, кремнезём; лёгкое ведение, но выше риск водорода/включений — смотрите назначение марки.</li><li><strong>Рутиловые (R)</strong> — удобный поджиг и стабильная дуга, хороший валик; распространены в учёбе и монтаже.</li><li><strong>Основные (B)</strong> — высокие механические свойства и низкий водород при правильной прокалке; требуют сухого хранения.</li><li><strong>Целлюлозные (C)</strong> — много газов защиты, удобны для некоторых корневых/вертикальных техник.</li></ul><p>По ГОСТ 9466/9467 задают размеры, виды покрытия и свойства. Выбор — по марке стали, положению, току/полярности и требованиям к ударной вязкости. Индексы на этикетке читайте по стандарту/паспорту.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> ГОСТ 9466, 9467; слайды МЦПК (состав обмазки, индексы).</div>",
