          "html": "<p>Основные параметры режима РДС: диаметр электрода, сила тока, род и полярность тока, длина дуги, скорость сварки, угол наклона электрода.</p>\n<p>Ориентир для нижнего положения: I ≈ (30–60)·d ампер, где d — диаметр стержня в мм. Для вертикали и потолка ток обычно снижают. Точные значения берут из таблиц/WPS для конкретной марки электрода.</p>\n<p>Подготовка: очистить кромки от ржавчины, масла, краски и влаги; собрать с заданным зазором; при необходимости выполнить разделку по ГОСТ 5264. Сборку фиксируют прихватками тем же типом электрода (если иное не указано).</p>\n<p>Плохая подготовка — частая причина пор, непровара и шлаковых включений. Экономия минут на зачистке часто оборачивается переделкой шва.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> ГОСТ 5264 — ручная дуговая сварка, сварные соединения.</div>",
