          "html": "<p>TIG (РАД): дуга между вольфрамовым электродом и изделием в инертном газе (обычно аргоне). При необходимости подают присадочный пруток. Электрод не должен плавиться при правильном режиме.</p><h3>Цветовая маркировка вольфрама (ориентир)</h3><ul><li><strong>WP (зелёный)</strong> — чистый вольфрам ≥99,5 %; чаще для алюминия на переменном токе.</li><li><strong>WL (чёрный/золотой/голубой)</strong> — лантанированные; универсальные, хороший поджиг и стойкость.</li><li><strong>WC (розовый/серый)</strong> — цериевые; стабильная дуга, меньше выгорание.</li><li><strong>WY (синий)</strong> — иттрированные; высокие токовые нагрузки.</li><li><strong>WZ (коричневый/белый)</strong> — циркониевые; для высоких токов, чаще AC.</li><li><strong>WT (жёлтый и др.)</strong> — торированные; хорошие сварочные свойства, но учитывайте требования по радиационной безопасности и замене на аналоги.</li></ul><p>Заточка, чистота и правильный вылет критичны: загрязнённый вольфрам портит шов. Электроды — ГОСТ 23949.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (вольфрамовые электроды); ГОСТ 23949.</div>",
