          "html": "<p>Аргон защищает вольфрам и ванну от воздуха. Расход и отсутствие сквозняка критичны: при срыве защиты появляются поры, окисление, «грязная» поверхность шва.</p>\n<p>Для большинства сталей используют постоянный ток прямой полярности. Для алюминия и магния часто применяют переменный ток — он помогает разрушать оксидную плёнку.</p>\n<p>Обратная полярность на постоянном токе сильнее нагружает электрод теплом и обычно не используется как основной режим TIG для сталей.</p>\n<p>Чистота газа, исправный шланг и плотное соединение горелки — такая же часть режима, как ток и скорость.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Выбор тока и газа — по Васильеву и WPS на материал.</div>",
