          "html": "<p>При полуавтоматической сварке плавящейся проволокой (MIG/MAG) механизм подаёт проволоку в зону дуги, а перемещение горелки вдоль шва выполняет сварщик.</p>\n<p>MIG — сварка в инертном газе (Ar, He); MAG — в активном газе или смеси с активным компонентом (часто CO₂ или Ar+CO₂). Для углеродистых сталей обычно говорят о MAG.</p>\n<p>Процесс высокопроизводителен, хорошо механизируется и широко применяется в производстве и монтаже. Качество зависит от настройки подачи, напряжения, газа и техники ведения горелки.</p>\n<p>Нормативная база дуговой сварки в защитном газе — ГОСТ 14771.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> ГОСТ 14771; технология — Васильев, гл. 11 и 15.</div>",
