          "html": "<p>Основные параметры: диаметр проволоки, ток, напряжение дуги, скорость подачи, скорость сварки, расход газа, вылет, наклон горелки.</p><h3>Как параметры влияют на шов</h3><ul><li><strong>Ток ↑</strong> — глубина проплавления ↑, доля основного металла в шве ↑.</li><li><strong>Напряжение ↑</strong> — ширина шва ↑, глубина ↓; избыток → разбрызгивание и хуже защита.</li><li><strong>Скорость сварки ↑</strong> — все размеры шва уменьшаются; риск непровара.</li><li><strong>Вылет ↑</strong> — хуже стабильность и формирование, больше брызг; слишком малый — трудно наблюдать процесс.</li><li><strong>Угол</strong> — «углом вперёд/назад» меняет провар и обзор кромок.</li></ul><p>Для углеродистых сталей — CO₂ или Ar+CO₂. Настройку подтверждают пробным валиком.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Слайды МЦПК (параметры режима в защитных газах).</div>",
