          "html": "<p>Сталью называют сплав железа с углеродом (до ~2,14 %) и другими элементами. По составу стали делят на углеродистые и легированные; по назначению — на конструкционные, инструментальные и специального назначения.</p>\n<p>Углеродистые стали обыкновенного качества обозначают «Ст» и номером (Ст3, Ст5). Буквы кп/пс/сп — степень раскисления: кипящая, полуспокойная, спокойная.</p>\n<p>Качественные углеродистые стали обозначают числом сотых долей углерода: сталь 20 ≈ 0,20 % C; сталь 45 ≈ 0,45 % C.</p>\n<p>От марки зависят свариваемость, необходимость подогрева и выбор присадочных материалов. Перед сваркой всегда уточняют марку по сертификату/чертежу.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Малеткина Т.Ю. Общая классификация и обозначение металлов и сплавов. — Томск: ТГУ, 2015.</div>",
