          "html": "<p>Алюминиевые деформируемые сплавы: Д16, АМг и др.; литейные часто обозначают АЛ. Медь — М1; латуни — Л63; бронзы — БрОФ, БрАЖ и др.</p>\n<p>Титановые сплавы: ВТ1-0, ВТ6. При их сварке критична защита от азота, кислорода и водорода — иначе шов становится хрупким.</p>\n<p>Для цветных металлов чаще применяют TIG/MIG в инертных газах, тщательную зачистку и контроль теплового режима.</p>\n<p>Не путайте «похожие» обозначения разных систем: буква в марке читается только в контексте стандарта на данный металл.</p><div class=\"lesson-note\"><strong>Норматив / пособие.</strong> Цветные сплавы — Малеткина; сварка цветных — Васильев.</div>",
